            page.getByText("Message sent").waitFor();
            assertEquals("", page.getByLabel("Name").inputValue());
            assertTrue(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).isDisabled());
            assertTrue(page.getByRole(AriaRole.GRIDCELL, new Page.GetByRoleOptions().setName("Hello from Chromium"))
                    .count() > 0 || page.getByText("Hello from Chromium").count() > 0);
        }
    }

