+package com.example.contact;
+
+import java.time.LocalDateTime;
+import java.time.format.DateTimeFormatter;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    private static final DateTimeFormatter SENT_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
+
+    private final ContactMessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send", e -> submit());
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog discardDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        // Any edit re-enables Send, which is disabled only right after a successful send
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        Shortcuts.addShortcutListener(this, () -> {
+            if (send.isEnabled()) {
+                submit();
+            }
+        }, Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setKey("name");
+        grid.addColumn(ContactMessage::email).setHeader("Email").setKey("email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setKey("phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setKey("message").setFlexGrow(3);
+        grid.addColumn(m -> m.sentAt().format(SENT_FORMAT)).setHeader("Sent").setKey("sent");
+        grid.setAllRowsVisible(true);
+
+        discardDialog.setHeaderTitle("Discard your message?");
+        discardDialog.add(new Paragraph("The form has unsent input. Leaving now will discard it."));
+        Button keepEditing = new Button("Keep editing", e -> discardDialog.close());
+        Button discard = new Button("Discard", e -> {
+            ContinueNavigationAction action = pendingNavigation;
+            pendingNavigation = null;
+            discardDialog.close();
+            if (action != null) {
+                action.proceed();
+            }
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        discardDialog.getFooter().add(keepEditing, discard);
+        // Closing the dialog any other way (Esc, outside click) keeps the user on this view
+        discardDialog.addOpenedChangeListener(e -> {
+            if (!e.isOpened() && pendingNavigation != null) {
+                pendingNavigation.cancel();
+                pendingNavigation = null;
+            }
+        });
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message);
+        form.setColspan(message, 2);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid, discardDialog);
+        refreshGrid();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasInput()) {
+            return;
+        }
+        pendingNavigation = event.postpone();
+        discardDialog.open();
+    }
+
+    private boolean hasInput() {
+        return !isEmpty(name) || !isEmpty(email) || !isEmpty(phone) || !isEmpty(message);
+    }
+
+    private static boolean isEmpty(HasValue<?, String> field) {
+        return field.getValue() == null || field.getValue().isEmpty();
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+        messageService.save(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue().trim(),
+                LocalDateTime.now()));
+        refreshGrid();
+        Notification.show("Message sent");
+
+        // Clear first: the value change listeners would re-enable Send otherwise
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue();
+
+        String nameError = nameValue.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            emailError = "Enter a valid e-mail address";
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (messageValue.trim().isEmpty()) {
+            messageError = "Message is required";
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        mark(name, nameError);
+        mark(email, emailError);
+        mark(message, messageError);
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static void mark(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        field.setErrorMessage(error);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAll());
+    }
+}
