+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+import com.microsoft.playwright.options.WaitForSelectorState;
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
+
+@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
+class ContactBrowserTest {
+
+    @Value("${local.server.port}")
+    int port;
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @BeforeAll
+    static void startBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void sendsMessageFromRealBrowser() {
+        try (Page page = browser.newPage()) {
+            page.navigate("http://localhost:" + port + "/contact");
+            page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("Contact")).waitFor();
+
+            page.getByLabel("Name").fill("Browser User");
+            page.getByLabel("Email").fill("browser@example.com");
+            page.locator("vaadin-text-area textarea").fill("Hello from Chromium");
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).click();
+
+            page.getByText("Message sent").waitFor();
+            assertEquals("", page.getByLabel("Name").inputValue());
+            assertTrue(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).isDisabled());
+            page.getByText("Hello from Chromium").first().waitFor();
+        }
+    }
+
+    @Test
+    void emptySubmitShowsErrorsInBrowser() {
+        try (Page page = browser.newPage()) {
+            page.navigate("http://localhost:" + port + "/contact");
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).click();
+
+            page.getByText("Name is required").waitFor();
+            page.getByText("Message is required").waitFor();
+        }
+    }
+
+    @Test
+    void aboutLinkAsksBeforeDiscardingInput() {
+        try (Page page = browser.newPage()) {
+            page.navigate("http://localhost:" + port + "/contact");
+            page.getByLabel("Name").fill("Keep me");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+            Locator openDialog = page.locator("vaadin-dialog[opened]");
+            openDialog.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.ATTACHED));
+            assertTrue(page.url().endsWith("/contact"));
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+            page.waitForFunction("() => !document.querySelector('vaadin-dialog[opened]')");
+            assertEquals("Keep me", page.getByLabel("Name").inputValue());
+
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            openDialog.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.ATTACHED));
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+            page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About")).waitFor();
+        }
+    }
+
+    @Test
+    void enterKeySendsFromRealBrowser() {
+        try (Page page = browser.newPage()) {
+            page.navigate("http://localhost:" + port + "/contact");
+            page.getByLabel("Name").fill("Enter Browser");
+            page.getByLabel("Phone").fill("123456");
+            page.locator("vaadin-text-area textarea").fill("Via Enter");
+            page.getByLabel("Phone").press("Enter");
+
+            page.getByText("Message sent").waitFor();
+            page.getByText("Via Enter").first().waitFor();
+        }
+    }
+}
