+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private ContactView view;
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void setUp() {
+        view = navigate(ContactView.class);
+        name = $(TextField.class).withCaption("Name").single();
+        email = $(EmailField.class).single();
+        phone = $(TextField.class).withCaption("Phone").single();
+        message = $(TextArea.class).single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    private long rows() {
+        return $(Grid.class).single().getGenericDataView().getItems().count();
+    }
+
+    @Test
+    void hasHeadingAndAboutLinkAndSendEnabledOnEmptyForm() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(send.isEnabled());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+    }
+
+    @Test
+    void blankFormShowsValidationErrorsAndSendsNothing() {
+        long before = rows();
+        test(send).click();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertFalse(phone.isInvalid());
+        assertEquals(before, rows());
+    }
+
+    @Test
+    void invalidEmailAndTooLongMessageAreRejected() {
+        name.setValue("Ann");
+        email.setValue("not-an-address");
+        message.setValue("x".repeat(501));
+        test(send).click();
+
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals("Ann", name.getValue());
+        assertEquals("not-an-address", email.getValue());
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndSendsMessage() {
+        long before = rows();
+        name.setValue("Phone Only");
+        phone.setValue("+358 40 123");
+        message.setValue("Call me");
+        test(send).click();
+
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+        assertEquals("", name.getValue());
+        assertEquals("", phone.getValue());
+        assertFalse(send.isEnabled());
+
+        assertEquals(before + 1, rows());
+    }
+
+    @Test
+    void enterSendsWhenValid() {
+        name.setValue("Enter User");
+        email.setValue("enter@example.com");
+        message.setValue("Hi");
+        fireShortcut(Key.ENTER);
+
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+    }
+
+    @Test
+    void editingAfterSendReEnablesSend() {
+        name.setValue("Edit User");
+        email.setValue("edit@example.com");
+        message.setValue("Hello");
+        test(send).click();
+        assertFalse(send.isEnabled());
+
+        name.setValue("Again");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void leavingWithInputIsPostponedUntilDiscarded() {
+        name.setValue("Half typed");
+        UI.getCurrent().navigate(AboutView.class);
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertEquals("Half typed", name.getValue());
+
+        $(Button.class).withText("Keep editing").single().click();
+        assertFalse(dialog.isOpened());
+        assertEquals("Half typed", name.getValue());
+
+        UI.getCurrent().navigate(AboutView.class);
+        $(Button.class).withText("Discard").single().click();
+        assertTrue($(H1.class).withText("About").exists());
+    }
+
+    @Test
+    void leavingEmptyFormIsNotInterrupted() {
+        UI.getCurrent().navigate(AboutView.class);
+        assertFalse($(Dialog.class).exists());
+        assertTrue($(H1.class).withText("About").exists());
+    }
+
+    @Test
+    void sentMessagesSurviveLeavingTheView() {
+        name.setValue("Persistent");
+        email.setValue("persist@example.com");
+        message.setValue("Remember me");
+        test(send).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        Grid<?> grid = $(Grid.class).single();
+        assertTrue(grid.getGenericDataView().getItems().anyMatch(m -> m instanceof ContactMessage cm
+                && cm.name().equals("Persistent")));
+    }
+}
